use verus::prelude::*;

verus! {

    /// Given a nonempty slice `a` and indices `s < e` with `e <= a.len()`,
    /// returns an index `min_i` in [s, e) such that for all k in [s,e),
    /// a[min_i] <= a[k].
    pub fn find_min_index(a: &[int], s: usize, e: usize) -> (min_i: usize)
        requires
            a.len() > 0,
            s < e,
            e <= a.len(),
        ensures
            // result is in the requested half‐open range
            s <= min_i && min_i < e,
        ensures
            // it's a minimum over that range
            forall |k: usize| (s <= k && k < e) ==> a[min_i] <= a[k]
    {
        // m = index of minimum seen so far
        let mut m = s;
        // i = next position to compare
        let mut i = s + 1;

        // Loop until we've scanned up to e
        while i < e
            invariant
                // m is always a valid index in [s, i)
                s <= m && m < i && i <= e,
            invariant
                // a[m] is minimal over the prefix [s, i)
                forall |k: usize| (s <= k && k < i) ==> a[m] <= a[k],
            decreases
                // measure for termination
                e - i
        {
            if a[i] < a[m] {
                m = i;
            }
            i += 1;
        }

        // At the end, i == e, so m is in [s, e) and minimal over [s, e)
        min_i = m;
    }

}